          const dm=r.domain,ck=dm&&dm.checks||[],nm={spf:"SPF",mx:T("MX (Email Routing, to receive at support@)","MX (Email Routing, para recibir en support@)","MX (Email Routing)","MX (Email Routing, para receber em support@)"),dmarc:"DMARC","resend-dkim":"DKIM (Resend)","resend-spf":"SPF (Resend, send)",bimi:T("BIMI (the logo in the inbox)","BIMI (el logo en la bandeja)","BIMI (Logo im Posteingang)","BIMI (o logo na caixa)")};
