  const fam=`<div class="an-tw"><table class="an-tb"><thead><tr><th>${esc(M3("Counter","Contador","Contador"))}</th><th>${esc(M3("From","Desde","De"))}</th><th>${esc(M3("Last day","Último día","Último dia"))}</th><th>${esc(M3("Accounts in 7 days","Cuentas en 7 días","Contas em 7 dias"))}</th><th></th></tr></thead><tbody>${F.map(x=>`<tr><td><b>${esc(ADM_FAM[x.fam]?M3(...ADM_FAM[x.fam]):x.fam)}</b> <small class="note mono">${esc(x.fam)}:</small></td><td>${esc(admDevName(x.device))}</td><td class="mono">${esc(x.last||"–")}</td><td class="mono">${admMNum(x.users7)}</td><td><span class="${st[x.state][0]}">${esc(st[x.state][1])}</span>${x.state==="quiet"?` <small class="note">${x.ago} ${esc(M3("days","días","dias"))}</small>`:""}</td></tr>`).join("")}</tbody></table></div>`;
  const defs=[[M3("Week","Semana","Semana"),M3("Monday to Sunday, UTC.","De lunes a domingo, UTC.","De segunda a domingo, UTC.")],[M3("Used it","Lo usó","Usou"),M3("Opened a screen of any app that day.","Abrió una pantalla de alguna app ese día.","Abriu uma tela de algum app naquele dia.")],[M3("Drove, raced","Condujo, corrió","Dirigiu, correu"),M3("Uploaded a session that day, and one of them was a race.","Subió una sesión ese día, y una de ellas fue una carrera.","Enviou uma sessão naquele dia, e uma delas foi uma corrida.")],[M3("Weekly user","Usuario semanal","Usuário semanal"),M3("Used it or drove in the week. The agent running in the background is counted apart.","Lo usó o condujo en la semana. El agente en segundo plano se cuenta aparte.","Usou ou dirigiu na semana. O agente em segundo plano é contado à parte.")],[M3("Drivers","Pilotos","Pilotos"),M3("Every account except the admins and the testers.","Todas las cuentas menos los admins y los testers.","Todas as contas menos os admins e os testers.")],[M3("Still using it a week later","Sigue usándolo una semana después","Ainda usa uma semana depois"),M3("A new account active on any of days 7 to 13 after the day it was created.","Una cuenta nueva activa en alguno de los días 7 a 13 tras el día en que se creó.","Uma conta nova ativa em algum dos dias 7 a 13 depois do dia em que foi criada.")],[M3("Source","Origen","Origem"),M3("The account's first visit, its tagged link, or the installer download's source for accounts made in the agent.","La primera visita de la cuenta, su enlace etiquetado o el origen de la descarga del instalador para las cuentas creadas en el agente.","A primeira visita da conta, seu link marcado ou a origem do download do instalador para as contas criadas no agente.")]];
  return admMCard(M3("Is every counter arriving","Llegan todos los contadores","Todos os contadores estão chegando"),M3("Each kind of counter and the device it comes from, with the last day it sent anything in 30 days. Stopped means it sent before and nothing came for 3 days.","Cada tipo de contador y el dispositivo del que viene, con el último día que envió algo en 30 días. Parado significa que enviaba y lleva 3 días sin llegar nada.","Cada tipo de contador e o dispositivo de onde vem, com o último dia em que enviou algo em 30 dias. Parou significa que enviava e há 3 dias não chega nada."),fam+(h.since&&h.since.usage?`<p class="note">${esc(M3("App usage is counted since","El uso de las apps se cuenta desde","O uso dos apps é contado desde"))} ${esc(h.since.usage)}.</p>`:""))
    +admMCard(M3("The weekly numbers","Los números semanales","Os números semanais"),M3("The server adds the weeks up once a day at 03:00 UTC and writes only what changed. Add up now does the last 15 weeks, Add up everything goes back to the first day there is.","El servidor suma las semanas una vez al día a las 03:00 UTC y escribe solo lo que cambió. Sumar ahora hace las últimas 15 semanas, y Sumar todo vuelve al primer día que hay.","O servidor soma as semanas uma vez por dia às 03:00 UTC e grava só o que mudou. Somar agora faz as últimas 15 semanas, e Somar tudo volta ao primeiro dia que existe."),
      `<dl class="kv adm-kv"><dt>${esc(M3("Last run","Última vez","Última vez"))}</dt><dd>${job&&job.at?esc(admAgo(job.at))+` · ${admMNum(job.weeks)} ${esc(M3("weeks","semanas","semanas"))} · ${admMNum(job.read)} ${esc(M3("rows read","filas leídas","linhas lidas"))} · ${admMNum(job.wrote)} ${esc(M3("written","escritas","gravadas"))} · ${admMNum(job.ms)} ms`:esc(M3("never","nunca","nunca"))}</dd></dl><div class="frow" style="gap:8px;flex-wrap:wrap"><button type="button" class="btn small primary" data-mrun="0">${esc(M3("Add up now","Sumar ahora","Somar agora"))}</button><button type="button" class="btn small" data-mrun="1">${esc(M3("Add up everything","Sumar todo","Somar tudo"))}</button><button type="button" class="btn small" id="admMCsv">${esc(M3("Download the weeks as CSV","Descargar las semanas en CSV","Baixar as semanas em CSV"))}</button></div>`)
