  const top=()=>{body.querySelectorAll("[data-mw]").forEach(b=>b.onclick=()=>{ADM.mw=+b.dataset.mw;reload()});body.querySelectorAll("[data-maud]").forEach(b=>b.onclick=()=>{ADM.maud=+b.dataset.maud;reload()})};
